 budgets(p){btn(p,'＋ 设置预算',()=>this.budgetForm(),'cm-primary');el(p,'p','cm-muted','总预算与分类预算分别显示；账户、人物筛选不会改变预算口径。预算按周 / 月 / 年循环应用。');const grid=el(p,'div','cm-grid');for(const b of this.d.budgets.filter(b=>!this.book||b.book===this.book)){const c=panel(grid);this.budgetCard(c,b);const actions=el(c,'div','cm-actions');btn(actions,'调整预算',()=>this.budgetForm(b),'cm-link');btn(actions,'删除',()=>new Confirm(this.p,'删除预算','历史账目会保留。',()=>this.p.change(d=>{d.budgets=d.budgets.filter(x=>x.id!==b.id);})).open(),'cm-link');}if(!this.d.budgets.length)empty(grid,'从一个能做到的预算开始');}
